  ('hls-leg-007', 'Bluebook - Wex Legal Dictionary and Glossary', 'Cornell Law School - Legal Information Institute', 'https://www.law.cornell.edu/', 'Legal', 'Beginner', 3, 'English', 'https://www.law.cornell.edu/wex/bluebook', 'free', 'Public law school site; no login required.', 'tutorial', 'Wex explainer on the Bluebook citation system: citation formats for cases, statutes, regulations and secondary sources.', true, '2026-10-30T00:00:00Z'),
  ('hls-leg-008', 'contract - Wex Legal Dictionary and Glossary', 'Cornell Law School - Legal Information Institute', 'https://www.law.cornell.edu/', 'Legal', 'Beginner', 3, 'English', 'https://www.law.cornell.edu/wex/contract', 'free', 'Public law school site; no login required.', 'tutorial', 'Wex explainer on contract law: the elements of a contract, formation, performance, breach and the remedies available.', true, '2026-10-30T00:00:00Z'),
  ('hls-leg-009', 'brief - Wex Legal Dictionary and Glossary', 'Cornell Law School - Legal Information Institute', 'https://www.law.cornell.edu/', 'Legal', 'Beginner', 3, 'English', 'https://www.law.cornell.edu/wex/brief', 'free', 'Public law school site; no login required.', 'tutorial', 'Wex explainer on the legal brief: its components, the standard of review and how briefs are prepared and read.', true, '2026-10-30T00:00:00Z'),
  ('hls-leg-010', 'discovery - Wex Legal Dictionary and Glossary', 'Cornell Law School - Legal Information Institute', 'https://www.law.cornell.edu/', 'Legal', 'Beginner', 3, 'English', 'https://www.law.cornell.edu/wex/discovery', 'free', 'Public law school site; no login required.', 'tutorial', 'Wex explainer on civil discovery: the discovery process, requests, interrogatories and the paralegal''s role in preparing and managing disclosure.', true, '2026-10-30T00:00:00Z'),
  ('hls-leg-011', 'due diligence - Wex Legal Dictionary and Glossary', 'Cornell Law School - Legal Information Institute', 'https://www.law.cornell.edu/', 'Legal', 'Beginner', 3, 'English', 'https://www.law.cornell.edu/wex/due_diligence', 'free', 'Public law school site; no login required.', 'tutorial', 'Wex explainer on legal due diligence: the investigations, document review and risk checks performed before a transaction or filing.', true, '2026-10-30T00:00:00Z'),
  ('hls-leg-012', 'litigation - Wex Legal Dictionary and Glossary', 'Cornell Law School - Legal Information Institute', 'https://www.law.cornell.edu/', 'Legal', 'Beginner', 3, 'English', 'https://www.law.cornell.edu/wex/litigation', 'free', 'Public law school site; no login required.', 'tutorial', 'Wex explainer on litigation: the stages of a civil case, the parties, motions, discovery, trial and settlement.', true, '2026-10-30T00:00:00Z'),
  ('hls-leg-013', 'dispute resolution - Wex Legal Dictionary and Glossary', 'Cornell Law School - Legal Information Institute', 'https://www.law.cornell.edu/', 'Legal', 'Beginner', 3, 'English', 'https://www.law.cornell.edu/wex/dispute_resolution', 'free', 'Public law school site; no login required.', 'tutorial', 'Wex explainer on dispute resolution methods, the role of negotiation and mediation, and when each route is appropriate.', true, '2026-10-30T00:00:00Z'),
  ('hls-leg-014', 'legal ethics - Wex Legal Dictionary and Glossary', 'Cornell Law School - Legal Information Institute', 'https://www.law.cornell.edu/', 'Legal', 'Beginner', 3, 'English', 'https://www.law.cornell.edu/wex/legal_ethics', 'free', 'Public law school site; no login required.', 'tutorial', 'Wex explainer on legal ethics and professional conduct: duties of confidentiality, competence, conflicts and the rules governing client handling.', true, '2026-10-30T00:00:00Z'),
  ('hls-leg-015', 'real property - Wex Legal Dictionary and Glossary', 'Cornell Law School - Legal Information Institute', 'https://www.law.cornell.edu/', 'Legal', 'Beginner', 3, 'English', 'https://www.law.cornell.edu/wex/real_property', 'free', 'Public law school site; no login required.', 'tutorial', 'Wex explainer on real property law: estates and interests, conveyancing, deeds, title and the documentation a matter file requires.', true, '2026-10-30T00:00:00Z'),
  ('hls-leg-016', 'electronic signature - Wex Legal Dictionary and Glossary', 'Cornell Law School - Legal Information Institute', 'https://www.law.cornell.edu/', 'Legal', 'Beginner', 3, 'English', 'https://www.law.cornell.edu/wex/electronic_signature', 'free', 'Public law school site; no login required.', 'tutorial', 'Wex explainer on electronic signatures: legal recognition under e-signature and electronic transaction statutes, consent, integrity and evidentiary use.', true, '2026-10-30T00:00:00Z'),
  ('hls-leg-017', 'Types of Cases', 'United States Courts (uscourts.gov)', 'https://www.uscourts.gov/', 'Legal', 'Beginner', 3, 'English', 'https://www.uscourts.gov/about-federal-courts/types-cases', 'free', 'Federal judiciary site; no login required.', 'tutorial', 'Official guide to the categories of federal cases - civil, criminal, bankruptcy and multi-district litigation - and how each is docketed and run.', true, '2026-10-30T00:00:00Z'),
  ('hls-leg-018', 'Find a Case (PACER)', 'United States Courts (uscourts.gov)', 'https://www.uscourts.gov/', 'Legal', 'Beginner', 4, 'English', 'https://www.uscourts.gov/court-records/find-case-pacER', 'free', 'Federal judiciary site; PACER itself charges per-query fees, the guide is free.', 'tutorial', 'Official guidance on using PACER to locate federal court records, with the case-finding workflow used for matter and file management.', true, '2026-10-30T00:00:00Z'),
  ('hls-leg-019', 'Court Programs', 'United States Courts (uscourts.gov)', 'https://www.uscourts.gov/', 'Legal', 'Beginner', 3, 'English', 'https://www.uscourts.gov/services-forms', 'free', 'Federal judiciary site; no login required.', 'tutorial', 'Index of federal court programs and the forms, services and self-help resources that matter and client services teams rely on.', true, '2026-10-30T00:00:00Z'),
  ('hls-leg-020', 'Caselaw Access Project', 'Caselaw Access Project (Harvard Law School Library)', 'https://case.law/', 'Legal', 'Beginner', 5, 'English', 'https://case.law/caselaw/', 'free', 'Public project site with full-text case law; no login required.', 'tutorial', 'Caselaw Access Project: a large open collection of United States case law for precedent research and legal analysis.', true, '2026-10-30T00:00:00Z'),
  ('hls-leg-022', 'Privacy in the Western World', 'Coursera (KU Leuven / Vrije Universiteit Brussel)', 'https://www.coursera.org/', 'Compliance', 'Beginner', 16, 'English', 'https://www.coursera.org/learn/privacy', 'audit', 'Course outline and modules are public; a free audit is available.', 'course', 'Course comparing EU, US and Asian privacy regimes, the rights individuals hold and the compliance duties organisations carry, with GDPR as the core case study.', true, '2026-10-30T00:00:00Z'),
  ('hls-leg-023', 'Professional Responsibility and Ethics for Accountants', 'Coursera (University of Illinois Urbana-Champaign)', 'https://www.coursera.org/', 'Legal', 'Beginner', 18, 'English', 'https://www.coursera.org/learn/ethics', 'audit', 'Course outline and modules are public; a free audit is available.', 'course', 'Course on professional and ethical duties in accounting practice: regulation, independence, control environments, documentation and evidence for audit work.', true, '2026-10-30T00:00:00Z'),
  ('hls-leg-024', 'GDPR Compliance Guidelines', 'GDPR.eu', 'https://gdpr.eu/', 'Compliance', 'Beginner', 8, 'English', 'https://gdpr.eu/compliance/', 'free', 'Public independent guidance site; no login required.', 'tutorial', 'Everything needed to work towards GDPR compliance: lawful basis, data subject rights, records of processing and breach handling.', true, '2026-10-30T00:00:00Z'),
  ('hls-leg-025', 'What is GDPR, the EU''s new data protection law?', 'GDPR.eu', 'https://gdpr.eu/', 'Compliance', 'Beginner', 3, 'English', 'https://gdpr.eu/what-is-gdpr/', 'free', 'Public independent guidance site; no login required.', 'tutorial', 'Plain-language overview of the GDPR: scope, roles, principles, lawful processing and the obligations that flow into contracts and day-to-day processing.', true, '2026-10-30T00:00:00Z'),
  ('hls-leg-026', 'Art. 30 GDPR - Records of processing activities', 'GDPR.eu', 'https://gdpr.eu/', 'Compliance', 'Beginner', 3, 'English', 'https://gdpr.eu/article-30-records-of-processing/', 'free', 'Public independent guidance site; no login required.', 'tutorial', 'Guidance on the Article 30 record of processing activities: what must be documented, who maintains it and how it evidences accountability.', true, '2026-10-30T00:00:00Z'),
  ('hls-leg-027', 'UK GDPR guidance and resources', 'Information Commissioner''s Office (ICO)', 'https://ico.org.uk/', 'Compliance', 'Beginner', 8, 'English', 'https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/', 'free', 'UK regulator site; no login required.', 'tutorial', 'The UK data protection regulator''s guidance hub on UK GDPR and Data Protection Act duties, including accountability, records of processing and enforcement.', true, '2026-10-30T00:00:00Z'),
  ('hls-leg-028', 'Training | IAPP', 'International Association of Privacy Professionals (IAPP)', 'https://iapp.org/', 'Compliance', 'Beginner', 4, 'English', 'https://iapp.org/train', 'free', 'Public training catalogue page; no login required to browse.', 'tutorial', 'IAPP''s privacy training catalogue covering privacy principles, certification tracks and practitioner development for privacy and compliance staff.', true, '2026-10-30T00:00:00Z'),
  ('hls-leg-029', 'CIPP/E: European Data Protection training', 'International Association of Privacy Professionals (IAPP)', 'https://iapp.org/', 'Compliance', 'Advanced', 20, 'English', 'https://iapp.org/train/cippe-training', 'free_with_limitations', 'Programme details are public; full course participation is a paid offering.', 'course', 'Privacy professional certification training covering European data protection law, accountability, data subject rights, cross-border transfers and regulator engagement.', true, '2026-10-30T00:00:00Z')
